M3colors* colors = ::ii::common::Appearance::instance().m3colors.get();
const js::Json json = js::parse(fileContent);
for (const auto& [key, value] : json.items()) {
  // key.replace(/_([a-z])/g, g => g[1].toUpperCase())
  std::string camelCaseKey;
  for (std::size_t i = 0; i < key.size(); ++i) {
    if (key[i] == '_' && i + 1 < key.size() && key[i + 1] >= 'a' && key[i + 1] <= 'z') {
      camelCaseKey += static_cast<char>(key[i + 1] - 'a' + 'A');
      ++i;
    } else {
      camelCaseKey += key[i];
    }
  }
  const std::string m3Key = "m3" + camelCaseKey;
  for (const auto& [name, member] : kMembers) {
    if (name == m3Key) {
      (colors->*member).set(qmlColor(value.is_string() ? value.get<std::string>() : std::string()));
    }
  }
}
colors->darkmode.set(qt::hslLightness(colors->m3background.get()) < 0.5);

